"use client";

import Image from "next/image";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import {
  ArrowLeft, ArrowRight, Bell, Boxes, Check, ChefHat, ChevronRight, CircleDollarSign, Clock3,
  CookingPot, Copy, CreditCard, Download, Eye, EyeOff, FileBarChart, LayoutDashboard, LockKeyhole, LogOut,
  Menu as MenuIcon, Minus, Package, Plus, QrCode, ReceiptText, RefreshCw, Search, Settings, ShoppingBag,
  SlidersHorizontal, Sparkles, Table2, TrendingUp, UtensilsCrossed, WalletCards, X,
} from "lucide-react";
import { toast } from "sonner";
import { Toaster } from "@/components/ui/sonner";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { RestaurantStoreProvider, useRestaurant } from "@/lib/restaurant-store";
import type { CartItem, Order, OrderStatus, Payment, PaymentMethod, Product, RestaurantState, TableStatus } from "@/lib/domain";
import { money, orderTotal, tableTotal } from "@/lib/domain";

const TABLE_STATUS: Record<TableStatus, { label: string; cls: string }> = {
  available: { label: "Livre", cls: "status-free" }, occupied: { label: "Ocupada", cls: "status-occupied" }, preparing: { label: "Preparando", cls: "status-preparing" }, ready: { label: "Pedido pronto", cls: "status-ready" }, closing: { label: "Aguardando conta", cls: "status-closing" },
};
const ORDER_STATUS: Record<OrderStatus, string> = { pending: "Pendente", confirmed: "Novo", preparing: "Preparando", ready: "Pronto", delivered: "Entregue", completed: "Concluído", cancelled: "Cancelado" };
const CATEGORIES = ["Todos", "Pizzas", "Pastéis", "Massas", "Bebidas", "Açaí", "Sorvetes"];
const paymentMethods: PaymentMethod[] = ["Pix", "Dinheiro", "Débito", "Crédito"];

function Topbar({ title, subtitle, back = "/operacao", action }: { title: string; subtitle?: string; back?: string; action?: React.ReactNode }) {
  return <header className="topbar"><div className="flex min-w-0 items-center gap-3"><Link href={back} className="icon-button" aria-label="Voltar"><ArrowLeft size={19} /></Link><div className="min-w-0"><h1 className="truncate text-xl font-semibold tracking-tight sm:text-2xl">{title}</h1>{subtitle && <p className="mt-0.5 truncate text-sm text-neutral-500">{subtitle}</p>}</div></div>{action}</header>;
}

function StatusPill({ status }: { status: TableStatus }) { const meta = TABLE_STATUS[status]; return <span className={`status-pill ${meta.cls}`}><span />{meta.label}</span>; }
function OrderPill({ status }: { status: OrderStatus }) { return <span className={`order-pill order-${status}`}>{ORDER_STATUS[status]}</span>; }
function Elapsed({ date }: { date: string }) { const time = new Intl.DateTimeFormat("pt-BR", { hour: "2-digit", minute: "2-digit", timeZone: "America/Sao_Paulo" }).format(new Date(date)); return <span>{time}</span>; }

function OperationHome() {
  const areas = [
    { href: "/operacao/garcom", label: "Garçom", note: "Mesas e comandas", icon: UtensilsCrossed, tone: "lime" },
    { href: "/operacao/cozinha", label: "Cozinha", note: "Fila de produção", icon: ChefHat, tone: "amber" },
    { href: "/operacao/caixa", label: "Caixa", note: "Contas e pagamentos", icon: CircleDollarSign, tone: "blue" },
    { href: "/gestao", label: "Gestão", note: "Indicadores e controle", icon: LayoutDashboard, tone: "violet" },
  ];
  return <main className="operation-entry"><div className="entry-shell"><header className="flex items-center justify-between border-b border-white/10 pb-6"><Brand dark /><Link href="/menu" className="entry-link">Abrir cardápio</Link></header><section className="flex flex-1 flex-col justify-center py-12"><div className="mb-10 max-w-2xl"><span className="live-pill"><span /> Operação aberta</span><h1 className="mt-5 text-4xl font-semibold leading-[1.04] tracking-[-.045em] sm:text-6xl">Onde você vai trabalhar agora?</h1><p className="mt-4 text-lg text-white/50">Escolha uma área para entrar. Garçom, cozinha e caixa têm acesso direto.</p></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{areas.map(({ href, label, note, icon: Icon, tone }) => <Link key={href} href={href} className="entry-card"><div className={`icon-tile icon-${tone}`}><Icon size={20} /></div><div className="mt-8 flex items-end justify-between"><div><h2 className="text-lg font-semibold">{label}</h2><p className="mt-1 text-sm text-white/45">{note}</p></div><ArrowRight size={19} className="text-white/30" /></div></Link>)}</div></section><footer className="flex justify-between border-t border-white/10 pt-5 text-xs text-white/35"><span>15 mesas configuradas</span><span>Sincronização ativa</span></footer></div></main>;
}

function Brand({ dark = false }: { dark?: boolean }) { return <div className="flex items-center gap-3"><span className="brand-mark"><UtensilsCrossed size={18} /></span><div><p className={`font-semibold tracking-tight ${dark ? "text-white" : "text-[#171814]"}`}>Restaurante</p><p className={`text-xs ${dark ? "text-white/40" : "text-neutral-500"}`}>Operação integrada</p></div></div>; }

function WaiterTables() {
  const { state } = useRestaurant();
  const summary = [
    ["Livres", state.tables.filter(t => t.status === "available").length], ["Em atendimento", state.tables.filter(t => ["occupied", "preparing"].includes(t.status)).length], ["Prontos", state.tables.filter(t => t.status === "ready").length], ["Fechamento", state.tables.filter(t => t.status === "closing").length],
  ];
  return <main className="app-page"><div className="page-container"><Topbar title="Salão" subtitle="Toque em uma mesa para abrir a comanda" action={<div className="hidden items-center gap-2 sm:flex"><span className="sync-dot" /> <span className="text-sm text-neutral-500">Ao vivo</span></div>} /><div className="summary-strip">{summary.map(([label, value]) => <div key={label}><strong>{value}</strong><span>{label}</span></div>)}</div><div className="mb-4 flex items-center justify-between"><h2 className="section-title">Mesas</h2><span className="text-sm text-neutral-500">{state.tables.filter(t => t.active).length} ativas</span></div><section className="table-grid">{state.tables.filter(t => t.active).map(table => { const orders = state.orders.filter(o => o.tableId === table.id && !["cancelled", "completed"].includes(o.status)); const total = tableTotal(state, table.id); return <Link key={table.id} href={`/operacao/garcom/mesa/${table.id}`} className={`table-card table-${table.status}`}><div className="flex items-start justify-between"><span className="table-number">{String(table.number).padStart(2, "0")}</span>{table.status === "ready" && <Bell size={18} className="text-emerald-600" />}</div><div className="mt-8"><StatusPill status={table.status} />{table.status !== "available" ? <><p className="mt-3 text-lg font-semibold">{money(total)}</p><p className="mt-1 text-xs text-neutral-500">{orders.length} {orders.length === 1 ? "pedido" : "pedidos"}</p></> : <p className="mt-3 text-sm text-neutral-400">Disponível para abrir</p>}</div></Link>; })}</section></div></main>;
}

function TableCommand({ tableId }: { tableId: string }) {
  const { state, cancelOrder } = useRestaurant(); const [adding, setAdding] = useState(false);
  const table = state.tables.find(t => t.id === tableId); const orders = state.orders.filter(o => o.tableId === tableId && o.status !== "cancelled" && o.status !== "completed");
  if (!table) return <NotFound />;
  if (adding) return <MenuBuilder tableId={tableId} source="waiter" onBack={() => setAdding(false)} onSent={() => setAdding(false)} />;
  const total = orders.reduce((sum, o) => sum + orderTotal(o), 0);
  return <main className="app-page"><div className="page-container max-w-4xl"><Topbar title={`Mesa ${String(table.number).padStart(2, "0")}`} subtitle={table.openedAt ? `Aberta às ${new Date(table.openedAt).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}` : "Mesa livre"} back="/operacao/garcom" action={<StatusPill status={table.status} />} />{orders.some(o => o.status === "ready") && <div className="ready-banner"><div className="ready-icon"><Bell size={20} /></div><div><strong>Pedido pronto para retirar</strong><p>A cozinha finalizou o pedido #{orders.find(o => o.status === "ready")?.number}.</p></div></div>}<section className="command-card"><div className="flex items-center justify-between border-b border-neutral-200 p-5 sm:p-6"><div><h2 className="section-title">Comanda</h2><p className="mt-1 text-sm text-neutral-500">{orders.length ? `${orders.length} pedido(s) ativo(s)` : "Nenhum pedido nesta mesa"}</p></div><button onClick={() => setAdding(true)} className="primary-button"><Plus size={18} /> Adicionar pedido</button></div><div className="divide-y divide-neutral-100">{orders.map(order => <div key={order.id} className="p-5 sm:p-6"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-3"><span className="order-number">#{order.number}</span><OrderPill status={order.status} /></div><div className="flex items-center gap-3 text-xs text-neutral-500"><Elapsed date={order.createdAt} />{order.status !== "ready" && <button onClick={() => { cancelOrder(order.id); toast.success("Pedido cancelado e estoque estornado"); }} className="text-red-600 hover:underline">Cancelar</button>}</div></div><div className="space-y-3">{order.items.map(item => <div key={item.id} className="flex justify-between gap-4"><div><p className="font-medium">{item.quantity}× {item.productName} <span className="text-neutral-400">· {item.variantName}</span></p>{item.addons.map(a => <p key={a.id} className="text-sm text-neutral-500">+ {a.name}</p>)}{item.note && <p className="mt-1 text-sm font-medium text-amber-700">Obs: {item.note}</p>}</div><strong className="whitespace-nowrap">{money(item.quantity * (item.unitPrice + item.addons.reduce((a, b) => a + b.price, 0)))}</strong></div>)}</div></div>)}{!orders.length && <div className="empty-state"><ReceiptText size={28} /><p>Esta mesa está livre.</p><button onClick={() => setAdding(true)} className="secondary-button">Abrir com um pedido</button></div>}</div>{orders.length > 0 && <div className="flex items-center justify-between border-t border-neutral-200 bg-neutral-50 p-5 sm:p-6"><span className="text-sm font-medium text-neutral-500">Total da comanda</span><strong className="text-2xl tracking-tight">{money(total)}</strong></div>}</section></div></main>;
}

function MenuBuilder({ tableId, source, publicMenu = false, onBack, onSent }: { tableId?: string; source: "waiter" | "qr"; publicMenu?: boolean; onBack?: () => void; onSent?: (number: number) => void }) {
  const { state, createOrder } = useRestaurant(); const [category, setCategory] = useState("Todos"); const [search, setSearch] = useState(""); const [selected, setSelected] = useState<Product | null>(null); const [cart, setCart] = useState<CartItem[]>([]); const [cartOpen, setCartOpen] = useState(false); const [success, setSuccess] = useState<number | null>(null);
  const filtered = state.products.filter(p => (category === "Todos" || p.category === category) && p.name.toLowerCase().includes(search.toLowerCase()));
  const total = cart.reduce((sum, item) => { const p = state.products.find(x => x.id === item.productId)!; const variant = p.variants.find(v => v.id === item.variantId)!; return sum + item.quantity * (variant.price + p.addons.filter(a => item.addonIds.includes(a.id)).reduce((a, b) => a + b.price, 0)); }, 0);
  const submit = () => {
    if (publicMenu && !tableId) { const lines = cart.map(i => { const p = state.products.find(x => x.id === i.productId)!; const variant = p.variants.find(v => v.id === i.variantId)!; const addons = p.addons.filter(a => i.addonIds.includes(a.id)).map(a => `\n+ ${a.name} — ${money(a.price)}`).join(""); return `${i.quantity}x ${p.name} ${variant.name} — ${money(i.quantity * (variant.price + p.addons.filter(a => i.addonIds.includes(a.id)).reduce((x, a) => x + a.price, 0)))}${addons}${i.note ? `\nObs: ${i.note}` : ""}`; }); const msg = `Olá! Gostaria de fazer um pedido:\n\n${lines.join("\n\n")}\n\nTotal: ${money(total)}\n\nNome:\nRetirada ou entrega:`; window.open(`https://wa.me/${state.settings.whatsapp}?text=${encodeURIComponent(msg)}`, "_blank", "noopener,noreferrer"); return; }
    if (!tableId) return; const result = createOrder(tableId, cart, source); if (!result.ok) { toast.error(result.message); return; } setCart([]); setCartOpen(false); setSuccess(result.number); onSent?.(result.number);
  };
  if (success) return <main className="customer-page"><div className="success-card"><span className="success-icon"><Check size={30} /></span><p className="text-sm font-semibold uppercase tracking-widest text-emerald-700">Pedido enviado</p><h1 className="mt-2 text-4xl font-semibold tracking-tight">Pedido #{success}</h1><p className="mt-3 text-neutral-500">Já enviamos para a cozinha. Você pode acompanhar com a equipe.</p><Link href={`/menu/mesa/${tableId}`} className="primary-button mt-7">Voltar ao cardápio</Link></div></main>;
  return <main className={publicMenu ? "customer-page" : "app-page"}><div className={publicMenu ? "customer-shell" : "page-container"}>{publicMenu ? <CustomerHeader tableId={tableId} /> : <Topbar title="Novo pedido" subtitle={`Mesa ${tableId}`} back="#" action={<button onClick={onBack} className="text-button">Cancelar</button>} />}{publicMenu && <div className="menu-hero"><Image src="/menu-hero.png" fill sizes="(max-width: 768px) 100vw, 720px" alt="Pizza de calabresa artesanal" className="object-cover" priority /><div className="menu-hero-overlay"><span className="live-pill"><Sparkles size={13} /> Feito na hora</span><h1>Seu pedido,<br />do seu jeito.</h1></div></div>}<div className="menu-toolbar"><div className="search-box"><Search size={18} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Buscar no cardápio" aria-label="Buscar produtos" /></div><div className="category-scroll">{CATEGORIES.map(c => <button key={c} onClick={() => setCategory(c)} className={category === c ? "category-chip active" : "category-chip"}>{c}</button>)}</div></div><section className="product-grid">{filtered.map(product => { const unavailable = !product.available || !isProductStockAvailable(state, product); return <button key={product.id} onClick={() => !unavailable && setSelected(product)} disabled={unavailable} className="product-card text-left"><div className="flex items-start justify-between gap-3"><div className={`product-symbol symbol-${product.category.toLowerCase().replace("ã", "a")}`}>{product.category === "Pizzas" ? "🍕" : product.category === "Bebidas" ? "🥤" : product.category === "Açaí" ? "🫐" : product.category === "Sorvetes" ? "🍨" : product.category === "Pastéis" ? "🥟" : "🍝"}</div>{unavailable ? <span className="sold-out">Indisponível</span> : <Plus size={18} className="text-neutral-400" />}</div><h3>{product.name}</h3><p>{product.description}</p><strong>A partir de {money(Math.min(...product.variants.map(v => v.price)))}</strong></button>; })}</section>{cart.length > 0 && <button onClick={() => setCartOpen(true)} className="cart-dock"><span className="cart-count">{cart.reduce((s, i) => s + i.quantity, 0)}</span><span>Ver pedido</span><strong>{money(total)}</strong></button>}<ProductDialog product={selected} open={!!selected} onOpenChange={open => !open && setSelected(null)} onAdd={item => { setCart(c => [...c, item]); setSelected(null); toast.success("Item adicionado"); }} /><CartSheet open={cartOpen} onOpenChange={setCartOpen} cart={cart} setCart={setCart} state={state} total={total} submit={submit} whatsapp={publicMenu && !tableId} /></div></main>;
}

function CustomerHeader({ tableId }: { tableId?: string }) { return <header className="customer-header"><Brand /><div className="text-right"><p className="text-xs uppercase tracking-wider text-neutral-400">{tableId ? "Você está na" : "Cardápio online"}</p><strong>{tableId ? `Mesa ${tableId}` : "Peça pelo WhatsApp"}</strong></div></header>; }

function isProductStockAvailable(state: RestaurantState, product: Product) { return product.variants.some(variant => (product.recipe[variant.id] ?? []).every(component => (state.stock.find(s => s.id === component.stockId)?.quantity ?? 0) >= component.quantity)); }

function ProductDialog({ product, open, onOpenChange, onAdd }: { product: Product | null; open: boolean; onOpenChange: (open: boolean) => void; onAdd: (item: CartItem) => void }) {
  const [variantId, setVariantId] = useState(""); const [addonIds, setAddonIds] = useState<string[]>([]); const [note, setNote] = useState(""); const [qty, setQty] = useState(1);
  // Resetting the form here is intentional: each newly selected product starts clean.
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { if (product) { setVariantId(product.variants[0]?.id ?? ""); setAddonIds([]); setNote(""); setQty(1); } }, [product]); if (!product) return null;
  const variant = product.variants.find(v => v.id === variantId) ?? product.variants[0]; const price = qty * (variant.price + product.addons.filter(a => addonIds.includes(a.id)).reduce((s, a) => s + a.price, 0));
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[92vh] overflow-y-auto rounded-3xl border-0 p-0 sm:max-w-xl"><DialogHeader className="border-b border-neutral-100 p-6 pr-12"><DialogTitle className="text-2xl">{product.name}</DialogTitle><DialogDescription className="text-base">{product.description}</DialogDescription></DialogHeader><div className="space-y-6 p-6"><div><label className="field-label">Escolha o tamanho</label><div className="grid gap-2 sm:grid-cols-3">{product.variants.map(v => <button key={v.id} onClick={() => setVariantId(v.id)} className={variantId === v.id ? "choice-card selected" : "choice-card"}><span>{v.name}</span><strong>{money(v.price)}</strong></button>)}</div></div>{product.addons.length > 0 && <div><label className="field-label">Adicionais</label><div className="space-y-2">{product.addons.map(a => <label key={a.id} className="addon-row"><input type="checkbox" checked={addonIds.includes(a.id)} onChange={() => setAddonIds(ids => ids.includes(a.id) ? ids.filter(id => id !== a.id) : [...ids, a.id])} /><span>{a.name}</span><strong>+ {money(a.price)}</strong></label>)}</div></div>}<div><label className="field-label" htmlFor="note">Observação</label><textarea id="note" value={note} onChange={e => setNote(e.target.value)} placeholder="Ex.: sem cebola" className="text-area" /></div><div className="flex items-center justify-between"><div className="quantity"><button onClick={() => setQty(q => Math.max(1, q - 1))}><Minus size={17} /></button><strong>{qty}</strong><button onClick={() => setQty(q => q + 1)}><Plus size={17} /></button></div><button onClick={() => onAdd({ key: crypto.randomUUID(), productId: product.id, variantId, addonIds, note, quantity: qty })} className="primary-button">Adicionar · {money(price)}</button></div></div></DialogContent></Dialog>;
}

function CartSheet({ open, onOpenChange, cart, setCart, state, total, submit, whatsapp }: { open: boolean; onOpenChange: (open: boolean) => void; cart: CartItem[]; setCart: React.Dispatch<React.SetStateAction<CartItem[]>>; state: RestaurantState; total: number; submit: () => void; whatsapp?: boolean }) {
  return <Sheet open={open} onOpenChange={onOpenChange}><SheetContent className="w-full sm:max-w-md"><SheetHeader className="border-b border-neutral-100 p-6"><SheetTitle className="text-xl">Seu pedido</SheetTitle><SheetDescription>{cart.reduce((s, i) => s + i.quantity, 0)} itens adicionados</SheetDescription></SheetHeader><div className="flex-1 overflow-y-auto p-6"><div className="space-y-5">{cart.map(item => { const p = state.products.find(x => x.id === item.productId)!; const v = p.variants.find(x => x.id === item.variantId)!; return <div key={item.key} className="cart-row"><div><p className="font-semibold">{item.quantity}× {p.name}</p><p className="text-sm text-neutral-500">{v.name}</p>{p.addons.filter(a => item.addonIds.includes(a.id)).map(a => <p key={a.id} className="text-sm text-neutral-500">+ {a.name}</p>)}{item.note && <p className="mt-1 text-sm text-amber-700">{item.note}</p>}</div><div className="text-right"><strong>{money(item.quantity * (v.price + p.addons.filter(a => item.addonIds.includes(a.id)).reduce((s, a) => s + a.price, 0)))}</strong><button onClick={() => setCart(c => c.filter(x => x.key !== item.key))} className="mt-2 block w-full text-right text-xs text-red-600">Remover</button></div></div>; })}</div></div><div className="border-t border-neutral-200 p-6"><div className="mb-5 flex items-center justify-between"><span className="text-neutral-500">Total</span><strong className="text-2xl">{money(total)}</strong></div><button onClick={submit} className="primary-button w-full justify-center">{whatsapp ? <><ShoppingBag size={18} /> Pedir pelo WhatsApp</> : <><CookingPot size={18} /> Enviar pedido</>}</button>{whatsapp && <p className="mt-3 text-center text-xs text-neutral-400">O pedido só será confirmado após o envio no WhatsApp.</p>}</div></SheetContent></Sheet>;
}

function Kitchen() {
  const { state, updateOrderStatus } = useRestaurant(); const [sector, setSector] = useState("Todos");
  const active = state.orders.filter(o => ["confirmed", "preparing", "ready"].includes(o.status) && (sector === "Todos" || o.items.some(i => i.sector === sector)));
  const columns: { status: OrderStatus; label: string }[] = [{ status: "confirmed", label: "Novos" }, { status: "preparing", label: "Preparando" }, { status: "ready", label: "Prontos" }];
  return <main className="kitchen-page"><div className="kitchen-shell"><Topbar title="Cozinha" subtitle={`${active.length} pedidos em produção`} action={<div className="hidden items-center gap-2 sm:flex"><Clock3 size={16} /><span className="text-sm font-medium">{new Date().toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}</span></div>} /><div className="sector-tabs">{["Todos", "Pizzaria", "Cozinha", "Sobremesas"].map(s => <button key={s} onClick={() => setSector(s)} className={sector === s ? "active" : ""}>{s}</button>)}</div><div className="kanban">{columns.map(column => { const orders = active.filter(o => o.status === column.status); return <section key={column.status} className="kanban-column"><div className="kanban-title"><span>{column.label}</span><b>{orders.length}</b></div><div className="space-y-3">{orders.map(order => <KitchenCard key={order.id} order={order} sector={sector} onAdvance={() => { const next = order.status === "confirmed" ? "preparing" : order.status === "preparing" ? "ready" : "delivered"; updateOrderStatus(order.id, next); toast.success(next === "preparing" ? "Preparo iniciado" : next === "ready" ? "Garçom avisado: pedido pronto" : "Pedido entregue"); }} />)}{!orders.length && <div className="kanban-empty"><Check size={20} /><span>Nenhum pedido</span></div>}</div></section>; })}</div></div></main>;
}

function KitchenCard({ order, sector, onAdvance }: { order: Order; sector: string; onAdvance: () => void }) { const items = sector === "Todos" ? order.items : order.items.filter(i => i.sector === sector); return <article className={`kitchen-card kitchen-${order.status}`}><div className="flex items-start justify-between"><div><span className="text-xs font-bold uppercase tracking-wider text-neutral-400">Pedido #{order.number}</span><h3 className="mt-1 text-xl font-semibold">Mesa {order.tableId}</h3></div><div className="text-right text-xs text-neutral-500"><p>{new Date(order.createdAt).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}</p><p className="mt-1 font-semibold"><Elapsed date={order.createdAt} /></p></div></div><div className="my-5 space-y-3">{items.map(i => <div key={i.id}><p className="font-semibold">{i.quantity}× {i.productName} <span className="font-normal text-neutral-500">{i.variantName}</span></p>{i.note && <p className="mt-1 rounded-lg bg-amber-50 px-3 py-2 text-sm font-bold text-amber-800">{i.note.toUpperCase()}</p>}</div>)}</div><button onClick={onAdvance} className={order.status === "ready" ? "secondary-button w-full justify-center" : "dark-button w-full justify-center"}>{order.status === "confirmed" ? "Iniciar preparo" : order.status === "preparing" ? "Marcar como pronto" : "Marcar entregue"}<ArrowRight size={17} /></button></article>; }

function Cashier() {
  const { state } = useRestaurant(); const [selectedId, setSelectedId] = useState<string | null>(null); const table = state.tables.find(t => t.id === selectedId);
  if (table) return <Checkout tableId={table.id} onBack={() => setSelectedId(null)} />;
  const open = state.tables.filter(t => t.status !== "available");
  return <main className="app-page"><div className="page-container"><Topbar title="Caixa" subtitle="Mesas abertas e pagamentos" /><div className="metric-grid compact"><Metric label="Mesas abertas" value={String(open.length)} icon={Table2} /><Metric label="Aguardando conta" value={String(state.tables.filter(t => t.status === "closing").length)} icon={ReceiptText} /><Metric label="Em aberto" value={money(open.reduce((s, t) => s + tableTotal(state, t.id), 0))} icon={WalletCards} /></div><h2 className="section-title mb-4">Contas abertas</h2><div className="cash-grid">{open.map(t => { const orders = state.orders.filter(o => o.tableId === t.id && !["completed", "cancelled"].includes(o.status)); return <button key={t.id} onClick={() => setSelectedId(t.id)} className="cash-card"><div className="flex items-start justify-between"><div><p className="text-sm text-neutral-500">Mesa</p><h3>{t.id}</h3></div><StatusPill status={t.status} /></div><div className="mt-8 flex items-end justify-between"><div><strong>{money(tableTotal(state, t.id))}</strong><p>{orders.length} {orders.length === 1 ? "pedido" : "pedidos"}</p></div><span className="open-account">Abrir conta <ChevronRight size={16} /></span></div></button>; })}</div></div></main>;
}

function Checkout({ tableId, onBack }: { tableId: string; onBack: () => void }) {
  const { state, payTable } = useRestaurant(); const orders = state.orders.filter(o => o.tableId === tableId && !["completed", "cancelled"].includes(o.status)); const subtotal = orders.reduce((s, o) => s + orderTotal(o), 0); const service = subtotal * state.settings.serviceRate / 100; const total = subtotal + service; const [payments, setPayments] = useState<Payment[]>([{ id: "pay-1", method: "Pix", amount: total }]); const paid = payments.reduce((s, p) => s + p.amount, 0);
  const addPayment = () => setPayments(p => [...p, { id: crypto.randomUUID(), method: "Crédito", amount: Math.max(0, total - paid) }]);
  return <main className="app-page"><div className="page-container max-w-5xl"><Topbar title={`Fechar mesa ${tableId}`} subtitle={`${orders.length} pedidos na comanda`} back="#" action={<button onClick={onBack} className="text-button">Voltar</button>} /><div className="checkout-layout"><section className="command-card"><div className="border-b border-neutral-100 p-6"><h2 className="section-title">Resumo da conta</h2></div><div className="divide-y divide-neutral-100 p-6">{orders.flatMap(o => o.items).map(item => <div key={item.id} className="flex justify-between py-3"><div><p className="font-medium">{item.quantity}× {item.productName}</p><p className="text-sm text-neutral-500">{item.variantName}</p></div><strong>{money(item.quantity * (item.unitPrice + item.addons.reduce((s, a) => s + a.price, 0)))}</strong></div>)}</div><div className="space-y-3 border-t border-neutral-200 bg-neutral-50 p-6 text-sm"><div className="flex justify-between text-neutral-500"><span>Subtotal</span><span>{money(subtotal)}</span></div><div className="flex justify-between text-neutral-500"><span>Taxa de serviço ({state.settings.serviceRate}%)</span><span>{money(service)}</span></div><div className="flex justify-between border-t border-neutral-200 pt-3 text-lg"><strong>Total</strong><strong>{money(total)}</strong></div></div></section><section className="payment-panel"><div><h2 className="section-title">Pagamento</h2><p className="mt-1 text-sm text-neutral-500">Aceita múltiplas formas</p></div><div className="space-y-3">{payments.map((p, index) => <div key={p.id} className="payment-row"><select value={p.method} onChange={e => setPayments(rows => rows.map((row, i) => i === index ? { ...row, method: e.target.value as PaymentMethod } : row))}>{paymentMethods.map(m => <option key={m}>{m}</option>)}</select><label><span>R$</span><input type="number" step="0.01" value={p.amount.toFixed(2)} onChange={e => setPayments(rows => rows.map((row, i) => i === index ? { ...row, amount: Number(e.target.value) } : row))} /></label>{payments.length > 1 && <button onClick={() => setPayments(rows => rows.filter((_, i) => i !== index))} aria-label="Remover pagamento"><X size={17} /></button>}</div>)}</div><button onClick={addPayment} className="secondary-button w-full justify-center"><Plus size={17} /> Dividir pagamento</button><div className="rounded-xl bg-neutral-100 p-4 text-sm"><div className="flex justify-between"><span className="text-neutral-500">Recebido</span><strong>{money(paid)}</strong></div>{Math.abs(total - paid) > .01 && <div className="mt-2 flex justify-between text-amber-700"><span>{paid < total ? "Falta" : "Troco"}</span><strong>{money(Math.abs(total - paid))}</strong></div>}</div><button disabled={paid + .01 < total} onClick={() => { payTable(tableId, payments); toast.success("Pagamento confirmado. Mesa liberada!"); onBack(); }} className="primary-button w-full justify-center"><Check size={18} /> Confirmar pagamento</button></section></div></div></main>;
}

function Metric({ label, value, note, icon: Icon }: { label: string; value: string; note?: string; icon: React.ComponentType<{ size?: number }>; }) { return <article className="metric-card"><div className="metric-icon"><Icon size={18} /></div><p>{label}</p><strong>{value}</strong>{note && <span>{note}</span>}</article>; }

const managementNav = [
  ["dashboard", "Dashboard", LayoutDashboard], ["mesas", "Mesas", Table2], ["pedidos", "Pedidos", ReceiptText], ["cardapio", "Cardápio", MenuIcon], ["estoque", "Estoque", Boxes], ["caixa", "Caixa", CircleDollarSign], ["relatorios", "Relatórios", FileBarChart], ["configuracoes", "Configurações", Settings],
] as const;

function Management({ section }: { section: string }) {
  const router = useRouter(); const [mobileNav, setMobileNav] = useState(false);
  useEffect(() => { if (sessionStorage.getItem("restaurante-auth") !== "ok") router.replace("/gestao"); }, [router]);
  const logout = () => { sessionStorage.removeItem("restaurante-auth"); router.push("/gestao"); };
  return <main className="management"><aside className={mobileNav ? "manage-sidebar open" : "manage-sidebar"}><div className="p-6"><Brand dark /></div><nav>{managementNav.map(([id, label, Icon]) => <Link key={id} href={`/gestao/${id}`} onClick={() => setMobileNav(false)} className={section === id ? "active" : ""}><Icon size={18} /><span>{label}</span></Link>)}</nav><button onClick={logout} className="logout-button"><LogOut size={17} /> Sair</button></aside>{mobileNav && <button className="sidebar-overlay" onClick={() => setMobileNav(false)} aria-label="Fechar menu" />}<div className="manage-content"><header className="manage-top"><button onClick={() => setMobileNav(true)} className="icon-button lg:hidden"><MenuIcon size={19} /></button><div><p className="text-xs font-semibold uppercase tracking-wider text-neutral-400">Gestão</p><h1 className="text-xl font-semibold capitalize">{managementNav.find(([id]) => id === section)?.[1] ?? section}</h1></div><div className="flex items-center gap-3"><span className="sync-dot" /><span className="hidden text-sm text-neutral-500 sm:block">Atualizado agora</span><div className="avatar">AD</div></div></header><div className="manage-page"><ManagementSection section={section} /></div></div></main>;
}

function Login() { const router = useRouter(); const [user, setUser] = useState("admin"); const [password, setPassword] = useState("admin123"); const [show, setShow] = useState(false); const submit = (e: React.FormEvent) => { e.preventDefault(); if (user === "admin" && password === "admin123") { sessionStorage.setItem("restaurante-auth", "ok"); router.push("/gestao/dashboard"); } else toast.error("Usuário ou senha inválidos"); }; return <main className="login-page"><section className="login-brand"><Brand dark /><div><span className="live-pill"><Sparkles size={13} /> Controle completo</span><h1>Decisões rápidas.<br />Operação sob controle.</h1><p>Acompanhe vendas, estoque, mesas e desempenho em um único lugar.</p></div><div className="login-metrics"><div><strong>R$ 7.842</strong><span>Faturamento hoje</span></div><div><strong>214</strong><span>Pedidos</span></div></div></section><section className="login-form-wrap"><form onSubmit={submit} className="login-card"><div className="login-lock"><LockKeyhole size={22} /></div><h2>Entrar na Gestão</h2><p>Use seu acesso administrativo.</p><label><span>Usuário</span><input value={user} onChange={e => setUser(e.target.value)} autoComplete="username" /></label><label><span>Senha</span><div className="password-field"><input value={password} onChange={e => setPassword(e.target.value)} type={show ? "text" : "password"} autoComplete="current-password" /><button type="button" onClick={() => setShow(v => !v)} aria-label="Mostrar senha">{show ? <EyeOff size={17} /> : <Eye size={17} />}</button></div></label><button className="primary-button w-full justify-center" type="submit">Entrar <ArrowRight size={18} /></button><div className="demo-credentials"><strong>Acesso de demonstração</strong><span>admin · admin123</span></div></form></section></main>; }

function ManagementSection({ section }: { section: string }) {
  if (section === "dashboard") return <Dashboard />; if (section === "mesas") return <ManageTables />; if (section === "pedidos") return <ManageOrders />; if (section === "cardapio") return <ManageMenu />; if (section === "estoque") return <Stock />; if (section === "caixa") return <CashReport />; if (section === "relatorios") return <Reports />; if (section === "configuracoes") return <Configuration />; return <NotFound />;
}

function Dashboard() {
  const { state } = useRestaurant(); const todaySales = state.sales.reduce((s, sale) => s + sale.total, 0) + 7686.3; const orderCount = 213 + state.sales.length; const avg = todaySales / 82;
  const bars = [34, 42, 31, 48, 62, 74, 92, 78, 96, 84, 68, 52]; const top = [["Pizza Calabresa", 148], ["Frango com Catupiry", 121], ["Açaí 500ml", 96], ["Coca-Cola 2L", 84]];
  return <><div className="page-heading"><div><h2>Visão geral</h2><p>Operação de hoje, 27 de setembro</p></div><button className="secondary-button"><Download size={17} /> Exportar</button></div><div className="metric-grid"><Metric label="Faturamento hoje" value={money(todaySales)} note="↑ 12,4% vs. sábado" icon={TrendingUp} /><Metric label="Pedidos" value={String(orderCount)} note="18 em andamento" icon={ReceiptText} /><Metric label="Mesas atendidas" value="82" note={`${state.tables.filter(t => t.status !== "available").length} abertas agora`} icon={Table2} /><Metric label="Ticket médio" value={money(avg)} note="↑ 4,2% esta semana" icon={CreditCard} /></div><div className="dashboard-grid"><section className="chart-card span-2"><div className="card-heading"><div><h3>Vendas por horário</h3><p>Faturamento acumulado de hoje</p></div><strong>R$ 7,8 mil</strong></div><div className="bar-chart">{bars.map((height, i) => <div key={i} className="bar-group"><div className="bar" style={{ height: `${height}%` }} /><span>{11 + i}h</span></div>)}</div></section><section className="chart-card"><div className="card-heading"><div><h3>Operação atual</h3><p>Salão em tempo real</p></div></div><div className="operation-ring"><div><strong>{state.tables.filter(t => t.status !== "available").length}</strong><span>mesas abertas</span></div></div><div className="operation-legend"><span><i className="bg-[#d7ff55]" /> Livres {state.tables.filter(t => t.status === "available").length}</span><span><i className="bg-[#ffb84c]" /> Em produção {state.tables.filter(t => ["preparing", "occupied"].includes(t.status)).length}</span><span><i className="bg-[#31b981]" /> Prontos {state.tables.filter(t => t.status === "ready").length}</span></div></section><section className="chart-card span-2"><div className="card-heading"><div><h3>Produtos mais vendidos</h3><p>Quantidade no dia</p></div><Link href="/gestao/relatorios">Ver relatório</Link></div><div className="rank-list">{top.map(([name, count], i) => <div key={name}><span className="rank">{i + 1}</span><strong>{name}</strong><div><i style={{ width: `${Number(count) / 1.5}%` }} /></div><b>{count}</b></div>)}</div></section><LowStockCard /></div></>;
}

function LowStockCard() { const { state } = useRestaurant(); const low = state.stock.filter(s => s.quantity <= s.minimum).slice(0, 4); return <section className="chart-card"><div className="card-heading"><div><h3>Estoque baixo</h3><p>Requer atenção</p></div><span className="alert-count">{low.length}</span></div><div className="low-list">{low.map(item => <div key={item.id}><span className="stock-icon"><Package size={16} /></span><div><strong>{item.name}</strong><p>{item.quantity.toLocaleString("pt-BR")} {item.unit} restantes</p></div></div>)}</div><Link href="/gestao/estoque" className="secondary-button mt-5 w-full justify-center">Ver estoque</Link></section>; }

function ManageTables() { const { state } = useRestaurant(); return <><PageTitle title="Mesas" subtitle="Acompanhe o salão e acesse links do cardápio por mesa." action="Criar mesa" /><div className="admin-table-grid">{state.tables.map(t => <div key={t.id} className="admin-table-card"><div><span>Mesa</span><strong>{t.id}</strong></div><StatusPill status={t.status} /><p>{t.status === "available" ? "Sem comanda aberta" : money(tableTotal(state, t.id))}</p><div><Link href={`/operacao/garcom/mesa/${t.id}`}>Abrir comanda</Link><Link href={`/menu/mesa/${t.id}`}>Link QR</Link></div></div>)}</div></>; }
function ManageOrders() { const { state, cancelOrder } = useRestaurant(); return <><PageTitle title="Pedidos" subtitle="Histórico e pedidos ativos da operação." /><div className="data-table"><div className="data-head"><span>Pedido</span><span>Mesa</span><span>Itens</span><span>Status</span><span>Total</span><span /></div>{[...state.orders].reverse().map(o => <div key={o.id} className="data-row"><strong>#{o.number}</strong><span>Mesa {o.tableId}</span><span>{o.items.reduce((s, i) => s + i.quantity, 0)} itens</span><OrderPill status={o.status} /><strong>{money(orderTotal(o))}</strong><button disabled={["completed", "cancelled"].includes(o.status)} onClick={() => cancelOrder(o.id)}>Cancelar</button></div>)}</div></>; }
function ManageMenu() { const { state, toggleProduct } = useRestaurant(); return <><PageTitle title="Cardápio" subtitle="Produtos, variantes, disponibilidade e setores de produção." action="Adicionar produto" /><div className="menu-admin-grid">{state.products.map(p => <article key={p.id} className="menu-admin-card"><div className="flex items-start justify-between"><span className="product-symbol">{p.category === "Pizzas" ? "🍕" : p.category === "Bebidas" ? "🥤" : p.category === "Açaí" ? "🫐" : "🍽️"}</span><button onClick={() => toggleProduct(p.id)} className={p.available ? "availability on" : "availability"}><i />{p.available ? "Disponível" : "Indisponível"}</button></div><h3>{p.name}</h3><p>{p.description}</p><div className="product-meta"><span>{p.category}</span><span>{p.sector}</span></div><div className="variant-list">{p.variants.map(v => <span key={v.id}>{v.name}<strong>{money(v.price)}</strong></span>)}</div></article>)}</div></>; }

function Stock() {
  const { state, adjustStock } = useRestaurant(); const [movement, setMovement] = useState<{ id: string; type: "Entrada" | "Ajuste" | "Perda" } | null>(null); const [qty, setQty] = useState(1); const low = state.stock.filter(s => s.quantity <= s.minimum); const out = state.stock.filter(s => s.quantity <= 0); const value = state.stock.reduce((s, i) => s + i.quantity * (i.cost ?? 0), 0);
  return <><PageTitle title="Estoque" subtitle="Controle simples, rastreável e conectado às vendas." action="Adicionar item" /><div className="metric-grid compact"><Metric label="Itens cadastrados" value={String(state.stock.length)} icon={Boxes} /><Metric label="Estoque baixo" value={String(low.length)} icon={SlidersHorizontal} /><Metric label="Sem estoque" value={String(out.length)} icon={Package} /><Metric label="Valor estimado" value={money(value)} icon={CircleDollarSign} /></div><div className="stock-layout"><section className="data-table stock-table"><div className="data-head"><span>Item</span><span>Categoria</span><span>Quantidade</span><span>Status</span><span>Ação</span></div>{state.stock.map(item => { const level = item.quantity <= 0 ? "out" : item.quantity <= item.minimum ? "low" : "ok"; return <div key={item.id} className="data-row"><strong>{item.name}</strong><span>{item.category}</span><span><b>{item.quantity.toLocaleString("pt-BR")}</b> {item.unit}</span><span className={`stock-level ${level}`}>{level === "out" ? "Sem estoque" : level === "low" ? "Baixo" : "Normal"}</span><button onClick={() => { setMovement({ id: item.id, type: "Entrada" }); setQty(1); }}>Movimentar</button></div>; })}</section><section className="movement-card"><h3>Últimas movimentações</h3><div>{[...state.movements].reverse().slice(0, 8).map(m => { const item = state.stock.find(s => s.id === m.stockId); return <div key={m.id}><span className={m.quantity > 0 ? "movement-plus" : "movement-minus"}>{m.quantity > 0 ? "+" : ""}{m.quantity.toLocaleString("pt-BR")} {item?.unit}</span><div><strong>{item?.name}</strong><p>{m.reference}</p></div><time>{new Date(m.createdAt).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}</time></div>; })}</div></section></div><Dialog open={!!movement} onOpenChange={open => !open && setMovement(null)}><DialogContent className="rounded-2xl sm:max-w-md"><DialogHeader><DialogTitle>Movimentar estoque</DialogTitle><DialogDescription>{state.stock.find(s => s.id === movement?.id)?.name}</DialogDescription></DialogHeader>{movement && <div className="space-y-4"><div className="grid grid-cols-3 gap-2">{(["Entrada", "Ajuste", "Perda"] as const).map(t => <button key={t} onClick={() => setMovement({ ...movement, type: t })} className={movement.type === t ? "choice-card selected" : "choice-card"}>{t}</button>)}</div><label className="block"><span className="field-label">Quantidade</span><input className="form-input" type="number" min="0" step="0.1" value={qty} onChange={e => setQty(Number(e.target.value))} /></label><button onClick={() => { adjustStock(movement.id, qty, movement.type); setMovement(null); toast.success("Movimentação registrada"); }} className="primary-button w-full justify-center">Confirmar movimentação</button></div>}</DialogContent></Dialog></>;
}

function CashReport() { const { state } = useRestaurant(); const total = state.sales.reduce((s, sale) => s + sale.total, 0); return <><PageTitle title="Caixa" subtitle="Vendas e formas de pagamento registradas." /><div className="metric-grid compact"><Metric label="Vendas registradas" value={String(state.sales.length + 81)} icon={ReceiptText} /><Metric label="Total no caixa" value={money(total + 7686.3)} icon={CircleDollarSign} /><Metric label="Pix" value={money(state.sales.flatMap(s => s.payments).filter(p => p.method === "Pix").reduce((s, p) => s + p.amount, 0) + 3180)} icon={QrCode} /></div><div className="data-table"><div className="data-head"><span>Venda</span><span>Mesa</span><span>Horário</span><span>Pagamento</span><span>Total</span></div>{[...state.sales].reverse().map(s => <div key={s.id} className="data-row"><strong>{s.id.slice(-6)}</strong><span>Mesa {s.tableId}</span><span>{new Date(s.createdAt).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}</span><span>{s.payments.map(p => p.method).join(" + ")}</span><strong>{money(s.total)}</strong></div>)}</div></>; }
function Reports() { return <><PageTitle title="Relatórios" subtitle="Leitura rápida do desempenho da operação." action="Exportar PDF" /><div className="report-filters"><button className="active">Hoje</button><button>7 dias</button><button>30 dias</button></div><div className="metric-grid"><Metric label="Faturamento" value="R$ 7.842,50" note="↑ 12,4%" icon={TrendingUp} /><Metric label="Pedidos" value="214" note="↑ 8,2%" icon={ReceiptText} /><Metric label="Ticket médio" value="R$ 95,64" note="↑ 4,2%" icon={CreditCard} /><Metric label="Mesas" value="82" note="71% ocupação" icon={Table2} /></div><div className="dashboard-grid"><section className="chart-card span-2"><div className="card-heading"><div><h3>Faturamento por categoria</h3><p>Participação nas vendas de hoje</p></div></div><div className="category-bars">{[["Pizzas", 48, "#171814"], ["Bebidas", 21, "#7eb9ff"], ["Pastéis", 14, "#ffb84c"], ["Açaí e sorvetes", 11, "#a887e8"], ["Massas", 6, "#31b981"]].map(([name, value, color]) => <div key={name}><span>{name}</span><div><i style={{ width: `${value}%`, background: String(color) }} /></div><strong>{value}%</strong></div>)}</div></section><section className="chart-card"><div className="card-heading"><div><h3>Formas de pagamento</h3><p>Distribuição das vendas</p></div></div><div className="donut"><div><strong>214</strong><span>pedidos</span></div></div><div className="payment-legend"><span><i className="bg-[#171814]" /> Pix 41%</span><span><i className="bg-[#7eb9ff]" /> Crédito 32%</span><span><i className="bg-[#ffb84c]" /> Débito 19%</span><span><i className="bg-[#d5d5cd]" /> Dinheiro 8%</span></div></section></div></>; }

function Configuration() { const { state, updateSettings, resetDemo } = useRestaurant(); const [settingsValue, setSettingsValue] = useState(state.settings); const [qrTable, setQrTable] = useState<string | null>(null); const origin = typeof window !== "undefined" ? window.location.origin : ""; const save = () => { updateSettings(settingsValue); toast.success("Configurações salvas"); }; return <><PageTitle title="Configurações" subtitle="Dados do restaurante, serviço e links das mesas." /><div className="settings-layout"><section className="settings-card"><h3>Dados do restaurante</h3><label><span>Nome do restaurante</span><input value={settingsValue.name} onChange={e => setSettingsValue(v => ({ ...v, name: e.target.value }))} /></label><label><span>WhatsApp</span><input value={settingsValue.whatsapp} onChange={e => setSettingsValue(v => ({ ...v, whatsapp: e.target.value }))} /></label><div className="grid grid-cols-2 gap-4"><label><span>Taxa de serviço (%)</span><input type="number" value={settingsValue.serviceRate} onChange={e => setSettingsValue(v => ({ ...v, serviceRate: Number(e.target.value) }))} /></label><label><span>Quantidade de mesas</span><input type="number" value={settingsValue.tableCount} disabled /></label></div><button onClick={save} className="primary-button">Salvar alterações</button></section><section className="settings-card"><div className="card-heading"><div><h3>Links e QR Codes</h3><p>Cardápio direto para cada mesa</p></div></div><div className="qr-list">{state.tables.slice(0, 8).map(t => <div key={t.id}><strong>Mesa {t.id}</strong><span>/menu/mesa/{t.id}</span><button onClick={() => setQrTable(t.id)}><QrCode size={16} /> Ver QR</button><button onClick={() => { navigator.clipboard.writeText(`${origin}/menu/mesa/${t.id}`); toast.success("Link copiado"); }} aria-label="Copiar link"><Copy size={16} /></button></div>)}</div></section><section className="settings-card danger-zone"><div><h3>Dados da demonstração</h3><p>Volte o sistema ao estado inicial com mesas, pedidos e estoque preenchidos.</p></div><button onClick={() => { resetDemo(); toast.success("Demonstração restaurada"); }} className="secondary-button"><RefreshCw size={17} /> Restaurar demonstração</button></section></div><Dialog open={!!qrTable} onOpenChange={open => !open && setQrTable(null)}><DialogContent className="rounded-3xl text-center sm:max-w-sm"><DialogHeader><DialogTitle>QR Code — Mesa {qrTable}</DialogTitle><DialogDescription>Aponte a câmera para abrir o cardápio da mesa.</DialogDescription></DialogHeader>{qrTable && <><div className="mx-auto rounded-2xl border border-neutral-200 bg-white p-3"><Image src={`https://api.qrserver.com/v1/create-qr-code/?size=240x240&data=${encodeURIComponent(`${origin}/menu/mesa/${qrTable}`)}`} width={240} height={240} alt={`QR Code da mesa ${qrTable}`} unoptimized /></div><button onClick={() => { navigator.clipboard.writeText(`${origin}/menu/mesa/${qrTable}`); toast.success("Link copiado"); }} className="secondary-button mx-auto"><Copy size={16} /> Copiar link</button></>}</DialogContent></Dialog></>;
}

function PageTitle({ title, subtitle, action }: { title: string; subtitle: string; action?: string }) { return <div className="page-heading"><div><h2>{title}</h2><p>{subtitle}</p></div>{action && <button className="primary-button"><Plus size={17} /> {action}</button>}</div>; }
function NotFound() { return <main className="app-page grid min-h-screen place-items-center"><div className="text-center"><p className="text-sm font-semibold uppercase tracking-wider text-neutral-400">404</p><h1 className="mt-2 text-3xl font-semibold">Página não encontrada</h1><Link href="/operacao" className="primary-button mt-6">Voltar à operação</Link></div></main>; }

function AppRouter() {
  const pathname = usePathname(); const { createOrder } = useRestaurant();
  useEffect(() => {
    const context = (document as Document & { modelContext?: { registerTool: (tool: unknown, options?: { signal?: AbortSignal }) => void | Promise<void> } }).modelContext;
    if (!context?.registerTool) return;
    const lifecycle = new AbortController();
    const tool = {
      name: "create_table_order",
      title: "Criar pedido de mesa",
      description: "Confirma um pedido real para uma mesa e envia à cozinha, usando IDs de produto e variante do cardápio.",
      inputSchema: {
        type: "object",
        properties: {
          tableId: { type: "string" },
          items: {
            type: "array",
            items: {
              type: "object",
              properties: { productId: { type: "string" }, variantId: { type: "string" }, quantity: { type: "number", minimum: 1 } },
              required: ["productId", "variantId", "quantity"],
              additionalProperties: false,
            },
          },
        },
        required: ["tableId", "items"],
        additionalProperties: false,
      },
      annotations: { readOnlyHint: false, untrustedContentHint: false },
      execute(input: unknown) {
        const value = input as { tableId: string; items: { productId: string; variantId: string; quantity: number }[] };
        if (!value?.tableId || !Array.isArray(value.items) || !value.items.length) throw new Error("Mesa e itens são obrigatórios");
        const result = createOrder(value.tableId, value.items.map((i, index) => ({ ...i, key: `tool-${index}`, addonIds: [] })), "waiter");
        if (!result.ok) throw new Error(result.message);
        return { orderNumber: result.number, status: "confirmed", tableId: value.tableId };
      },
    };
    try { void Promise.resolve(context.registerTool(tool, { signal: lifecycle.signal })).catch(() => {}); } catch { /* unsupported context */ }
    return () => lifecycle.abort();
  }, [createOrder]);
  if (pathname === "/operacao") return <OperationHome />; if (pathname === "/operacao/garcom") return <WaiterTables />; if (pathname.startsWith("/operacao/garcom/mesa/")) return <TableCommand tableId={pathname.split("/").pop()!} />; if (pathname === "/operacao/cozinha") return <Kitchen />; if (pathname === "/operacao/caixa") return <Cashier />; if (pathname === "/menu") return <MenuBuilder source="qr" publicMenu />; if (pathname.startsWith("/menu/mesa/")) return <MenuBuilder source="qr" publicMenu tableId={pathname.split("/").pop()!} />; if (pathname === "/gestao") return <Login />; if (pathname.startsWith("/gestao/")) return <Management section={pathname.split("/").pop() || "dashboard"} />; return <NotFound />;
}

export default function RestaurantApp() {
  const [mounted, setMounted] = useState(false);
  // The local demo store is browser-only; wait for hydration before rendering it.
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => setMounted(true), []);
  if (!mounted) return <main className="app-page min-h-screen" aria-busy="true" />;
  return <RestaurantStoreProvider><AppRouter /><Toaster position="top-center" richColors /></RestaurantStoreProvider>;
}
